// Disposable UI study: four Android directions, synthetic data, memory-only state.
const icons = {
 arrow:'<path d="m9 5 7 7-7 7"/>', back:'<path d="m14 5-7 7 7 7"/>', up:'<path d="m7 17 10-10M7 7h10v10"/>',
 home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',
 chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/>',
 widget:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 settings:'<path d="m9 3-1 3-3 1-1 3 2 2-2 2 1 3 3 1 1 3h6l1-3 3-1 1-3-2-2 2-2-1-3-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',
 plus:'<path d="M12 5v14M5 12h14"/>', check:'<path d="m5 12 4 4L19 6"/>',
 refresh:'<path d="M20 10a8 8 0 0 0-14-4L3 9m0-5v5h5M4 14a8 8 0 0 0 14 4l3-3m0 5v-5h-5"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',
 system:'<rect x="4" y="3" width="16" height="13" rx="2"/><path d="M12 16v5M8 21h8"/>',
 moon:'<path d="M20 15a8 8 0 0 1-11-11 9 9 0 1 0 11 11Z"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 games:'<rect x="3" y="5" width="18" height="14" rx="4"/><path d="M6 12h6M9 9v6M16 10h.01M18 14h.01"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
 wifi:'<path d="M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0M9 16a5 5 0 0 1 6 0M12 20h.01"/>',
 battery:'<rect x="3" y="7" width="17" height="10" rx="2"/><path d="M22 10v4M6 10h10v4H6Z"/>',
 signal:'<path d="M5 20v-3M10 20v-7M15 20V9M20 20V4"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.info}</svg>`;
const fmt = value => new Intl.NumberFormat('en-US').format(value);
const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const directions = {
 A:{name:'Pulse',subtitle:'Your portfolio, at a glance.',summary:'A calm overview. All your games together, with just enough detail to spot what changed.',purpose:'For the quick morning check: understand the whole portfolio, then open the game that needs a closer look.',class:'a',colors:['#f3f7f6','#236d54','#d9eadd','#19352f'],features:['Portfolio comes first','History sits beside the total','One tap from overview to a game'],risk:'The portfolio total can hide differences between games. Per-game rows keep those changes visible.',signature:'A continuous portfolio history connects the current balance to its recent movement.'},
 B:{name:'Ledger',subtitle:'The numbers, side by side.',summary:'A compact reporting view. Compare games, additions, and net changes without opening each one.',purpose:'For a deliberate review: compare the performance of multiple games over the same reporting window.',class:'b',colors:['#f9fafc','#254d8d','#e2eafa','#253850'],features:['Activity leads the screen','Games share a comparison table','Additions and net change stay distinct'],risk:'Higher information density asks for more attention. It is less suited to a two-second glance.',signature:'A shared reporting table makes differences between games immediately comparable.'},
 C:{name:'Focus',subtitle:'One game. The full picture.',summary:'An immersive game-first view. Move between games and follow a single title’s progress.',purpose:'For the developer who is focused on one launch: the selected game stays at the center of every report.',class:'c',colors:['#201f2b','#d7c3fa','#40364f','#b7d7b4'],features:['Game picker stays within reach','Large, game-specific history','A milestone gives progress context'],risk:'Checking a whole portfolio takes more switching. The game picker keeps that cost explicit.',signature:'Game artwork anchors the report; changing games updates the entire working area.'},
 D:{name:'Signal',subtitle:'Start with what changed.',summary:'A daily briefing. New additions, game updates, and milestones arranged as a readable activity feed.',purpose:'For checking in between other tasks: read the latest reporting update and decide whether anything needs attention.',class:'d',colors:['#fbf5eb','#94502d','#f1dfc7','#443428'],features:['The latest update leads','A timeline replaces the dashboard grid','Notification rules are one tap away'],risk:'The feed favors recent activity. Longer-term analysis sits one step deeper in the report.',signature:'A dated briefing turns the same reporting data into a sequence of meaningful updates.'}
};
const games = [
 {id:101,name:'Mosslight',art:'mosslight.svg',total:12480,latest:128,deleted:14,purchased:2,goal:15000,caption:'A little light. A long way home.'},
 {id:102,name:'Orbital Drift',art:'orbital.svg',total:8240,latest:37,deleted:5,purchased:1,goal:10000,caption:'Find your orbit.'},
 {id:103,name:'Tiny Harbor',art:'harbor.svg',total:4140,latest:19,deleted:3,purchased:0,goal:5000,caption:'Make a place by the water.'}
];
for (const [gi,game] of games.entries()) {
 game.days = Array.from({length:90},(_,i)=>{
  const date = new Date(Date.UTC(2026,7,18+i)).toISOString().slice(0,10);
  const adds = i===89 ? game.latest : Math.round((game.latest*.45)+(i/89*game.latest*.3)+Math.sin(i*1.7+gi)*game.latest*.18+(i%13===0?game.latest*.6:0));
  const deletes = i===89 ? game.deleted : Math.max(0,Math.round(adds*.11+(i%4)));
  const purchases = i===89 ? game.purchased : Math.round(adds*.025);
  return {date,adds,deletes,purchases,gifts:0,net:adds-deletes-purchases};
 });
 let balance=game.total;
 for(let i=89;i>=0;i--){game.days[i].balance=balance;balance-=game.days[i].net;}
}
const createState = key => ({screen:'overview',gameId:101,range:key==='B'?'7':'30',metric:'adds',customStart:'2026-11-01',customEnd:'2026-11-15',notifications:true,threshold:10,digest:true,quiet:true,quietStart:'22:00',quietEnd:'08:00',widgetGame:101,widgetMetric:'balance',offline:false,empty:false,feedback:'',selected:key==='C',theme:'system'});
const states = Object.fromEntries(Object.keys(directions).map(key=>[key,createState(key)]));
const systemTheme = window.matchMedia('(prefers-color-scheme: dark)');
const themeModes = ['system', 'light', 'dark'];
const initialParams = new URL(location.href).searchParams;
if (themeModes.includes(initialParams.get('theme'))) states.C.theme = initialParams.get('theme');
let activeKey = initialParams.get('variant') || 'C';
if (!directions[activeKey]) activeKey = 'C';
let compare = initialParams.get('view') === 'compare';
function resolvedTheme() {
 return states.C.theme === 'system' ? (systemTheme.matches ? 'dark' : 'light') : states.C.theme;
}
function paletteFor(key) {
 return key === 'C' && resolvedTheme() === 'light' ? ['#faf8fd','#74539a','#e9dff4','#306c43'] : directions[key].colors;
}
function appearanceControls(key) {
 if (key !== 'C') return '';
 return `<fieldset class="appearance-panel"><legend>Appearance</legend><div class="appearance-options" role="group" aria-label="Focus appearance">${[['system','System','system'],['light','Light','sun'],['dark','Dark','moon']].map(([value,label,glyph])=>`<button type="button" data-appearance="${value}" aria-pressed="${states.C.theme===value}">${icon(glyph)}${label}</button>`).join('')}</div><p class="appearance-caption">${states.C.theme==='system'?`Following your device · ${resolvedTheme()} mode`:`${resolvedTheme()==='light'?'Light':'Dark'} mode · manual override`}</p></fieldset>`;
}
function themeSetting(key, state) {
 if (key !== 'C') return '';
 return `<div class="settings-group"><h3>Appearance</h3><label class="form-label" for="${key}-theme">App theme</label><select id="${key}-theme" class="form-control" data-field="theme">${themeModes.map(value=>`<option value="${value}" ${state.theme===value?'selected':''}>${value==='system'?'Follow system':value==='light'?'Light':'Dark'}</option>`).join('')}</select><p class="helper">Applies to all screens and this widget preview. System mode follows your device automatically.</p></div>`;
}
function setTheme(mode) {
 if (!themeModes.includes(mode)) return;
 states.C.theme = mode;
 const url = new URL(location.href);
 url.searchParams.set('theme', mode);
 history.replaceState({}, '', url);
 refreshPhone('C', {preserveScroll:true});
 const panel = document.querySelector('.appearance-panel');
 if (panel) panel.outerHTML = appearanceControls('C');
 const palette = panel?.closest('.direction-info')?.querySelector('.palette');
 if (palette) palette.innerHTML = paletteFor('C').map(color=>`<span style="background:${color}"></span>`).join('');
}

const selectedGame = state => games.find(g=>g.id===state.gameId)||games[0];
const scopeGames = (state, single=false) => single?[selectedGame(state)]:games;
function rowsFor(state,single=false){
 const source=scopeGames(state,single);
 let rows=source[0].days.map((day,i)=>({date:day.date,adds:source.reduce((s,g)=>s+g.days[i].adds,0),deletes:source.reduce((s,g)=>s+g.days[i].deletes,0),purchases:source.reduce((s,g)=>s+g.days[i].purchases,0),gifts:0,net:source.reduce((s,g)=>s+g.days[i].net,0),balance:source.reduce((s,g)=>s+g.days[i].balance,0)}));
 return state.range==='custom'?rows.filter(r=>r.date>=state.customStart&&r.date<=state.customEnd):rows.slice(-Number(state.range));
}
const sum = (rows,field) => rows.reduce((acc,row)=>acc+row[field],0);
const latestTotal = () => games.reduce((acc,g)=>acc+g.total,0);
function dayLabel(date){return new Date(`${date}T12:00:00Z`).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'});}
function chart(state,single=false,bars=false,metric=state.metric){
 const rows=rowsFor(state,single);
 if(!rows.length)return '<div class="chart-empty">No reports in this date range.</div>';
 const data=rows.map(row=>row[metric]);
 const max=Math.max(...data,1), min=metric==='balance'?Math.min(...data)*.985:0;
 const y=v=>126-(v-min)/(max-min||1)*105;
 const x=i=>8+i/Math.max(1,data.length-1)*260;
 const labels=[max,Math.round((max+min)/2),Math.round(min)];
 const labelValue = n=>n>=1000?`${(n/1000).toFixed(1)}k`:fmt(n);
 let mark='';
 if(bars){const gap=268/data.length;mark=data.map((n,i)=>`<rect x="${i*gap+3}" y="${y(n)}" width="${Math.max(1,gap*.62)}" height="${Math.max(1,126-y(n))}" rx="2" fill="var(--primary)" opacity="${i===data.length-1?1:.5}"><title>${dayLabel(rows[i].date)}: ${fmt(n)} ${metric==='net'?'net change':'additions'}</title></rect>`).join('');}
 else{const points=data.map((n,i)=>`${x(i)},${y(n)}`).join(' ');const area=`M${x(0)},126 L${points.split(' ').join(' L')} L${x(data.length-1)},126Z`;mark=`<path d="${area}" fill="var(--primary)" opacity=".07"/><polyline class="chart-line" points="${points}"/><circle class="chart-dot" cx="${x(data.length-1)}" cy="${y(data.at(-1))}" r="4"/>`;}
 const name=metric==='balance'?'Derived wishlist balance':metric==='net'?'Net wishlist change':'Wishlist additions';
 return `<figure class="chart" aria-label="${esc(name)} from ${dayLabel(rows[0].date)} to ${dayLabel(rows.at(-1).date)}"><svg viewBox="0 0 310 150" role="img"><title>${esc(name)}. ${rows.length} reporting days. ${metric==='balance'?`Latest balance ${fmt(data.at(-1))}`:`Total ${fmt(sum(rows,metric))}`}.</title>${[21,73.5,126].map((yy,i)=>`<line class="grid-line" x1="0" y1="${yy}" x2="274" y2="${yy}"/><text class="chart-label" x="283" y="${yy+3}">${labelValue(labels[i])}</text>`).join('')}${mark}<text class="chart-label" x="0" y="147">${dayLabel(rows[0].date)}</text><text class="chart-label" x="268" y="147" text-anchor="end">${dayLabel(rows.at(-1).date)}</text></svg></figure>`;
}
function chips(state){return `<div class="chips" aria-label="Reporting interval">${[['7','7 days'],['30','30 days'],['90','90 days'],['custom','Custom']].map(([value,label])=>`<button class="chip" data-action="range" data-value="${value}" aria-pressed="${state.range===value}">${label}</button>`).join('')}</div>${state.range==='custom'?`<div class="custom-range"><label>From<input class="form-control" type="date" data-field="customStart" value="${state.customStart}" min="2026-08-18" max="2026-11-15"></label><label>Through<input class="form-control" type="date" data-field="customEnd" value="${state.customEnd}" min="2026-08-18" max="2026-11-15"></label></div>${state.customStart>state.customEnd?'<p class="helper">Choose an end date on or after the start date.</p>':''}`:''}`;}
function metrics(state,single=false){const rows=rowsFor(state,single);return `<div class="mini-stats"><div><span>Additions</span><strong>${fmt(sum(rows,'adds'))}</strong></div><div><span>Removed</span><strong>${fmt(sum(rows,'deletes'))}</strong></div><div><span>Net change</span><strong class="positive">+${fmt(sum(rows,'net'))}</strong></div></div>`;}
function reportDate(state){return `<p class="report-date"><span class="report-dot"></span>${state.offline?'Offline · cached report':'Demo · report through'} Nov 15, 2026 · GMT</p>`;}
function gameRows(state){return games.map(g=>`<button class="game-row" data-action="game" data-value="${g.id}"><img class="game-thumb" src="./assets/${g.art}" alt=""><span class="game-name">${esc(g.name)}<small>Derived balance</small></span><span class="game-count">${fmt(g.total)}<small>+${g.latest} additions</small></span></button>`).join('');}
function appbar(title,back=false){return `<div class="appbar">${back?`<button class="icon-button" data-action="back" aria-label="Back to overview">${icon('back')}</button>`:''}<div class="top-title"><h2>${title}</h2>${!back?'<span class="demo-badge">Demo</span>':''}</div><button class="icon-button" data-action="${back?'screen':'sync'}" ${back?'data-value="alerts" aria-label="Notification settings"':'aria-label="Simulate synchronization"'}>${icon(back?'bell':'refresh')}</button></div>`;}
function overviewA(state){return `${appbar('Overview')}<div class="app-content">${reportDate(state)}<p class="metric-label">Derived wishlist balance · all games</p><div class="metric-inline"><p class="main-number">${fmt(latestTotal())}</p><span class="metric-change">+159 net</span></div><p class="metric-sub">184 additions in the latest daily report</p>${chips(state)}${chart(state,false,false,'balance')}${metrics(state)}<div class="section-heading"><h3>Your games</h3><button class="text-button" data-action="screen" data-value="add">${icon('plus')} Add game</button></div>${gameRows(state)}<p class="helper">Demo totals use a dated starting balance.</p></div>`;}
function overviewB(state){const rows=rowsFor(state);return `${appbar('Reports')}<div class="app-content">${reportDate(state)}<div class="blue-banner"><p class="metric-label">Wishlist additions · selected interval</p><div class="metric-inline"><p class="main-number">${fmt(sum(rows,'adds'))}</p><span class="metric-change">${rows.length} reporting days</span></div><p class="metric-sub">Across ${games.length} games · ${rows.length?`${dayLabel(rows[0].date)}–${dayLabel(rows.at(-1).date)}`:'empty interval'}</p></div>${chips(state)}<div class="section-heading"><h3>Daily activity</h3><select class="metric-select form-control" data-field="metric" aria-label="Chart metric" style="width:105px;min-height:38px;padding:7px;font-size:10px"><option value="adds" ${state.metric==='adds'?'selected':''}>Additions</option><option value="net" ${state.metric==='net'?'selected':''}>Net change</option></select></div>${chart(state,false,true)}<div class="section-heading"><h3>Compare games</h3><button class="text-button" data-action="screen" data-value="add" aria-label="Add game">${icon('plus')}</button></div><table class="data-table"><thead><tr><th scope="col">Game</th><th scope="col">Adds</th><th scope="col">Net</th></tr></thead><tbody>${games.map(g=>{const subset=state.range==='custom'?g.days.filter(d=>d.date>=state.customStart&&d.date<=state.customEnd):g.days.slice(-Number(state.range));return `<tr><td><button class="table-game" data-action="game" data-value="${g.id}"><img src="./assets/${g.art}" alt="">${esc(g.name)}</button></td><td>${fmt(sum(subset,'adds'))}</td><td class="positive">+${fmt(sum(subset,'net'))}</td></tr>`;}).join('')}</tbody></table><p class="table-note">Net = additions − removals − purchases − gifts.<br>Reporting dates use GMT.</p><button class="outlined-button" data-action="export">${icon('download')} Export this report</button></div>`;}
function gameTabs(state){return `<div class="game-tabs" aria-label="Select game">${games.map(g=>`<button class="game-tab" aria-pressed="${state.gameId===g.id}" data-action="select-game" data-value="${g.id}">${esc(g.name)}</button>`).join('')}</div>`;}
function overviewC(state){const g=selectedGame(state);return `${appbar('Your games')}${gameTabs(state)}<div class="focus-art"><img src="./assets/${g.art}" alt="Illustrative artwork for ${esc(g.name)}"><div class="art-caption"><h3>${esc(g.name)}</h3><span>${g.caption}</span></div></div><div class="app-content">${reportDate(state)}<div class="focus-balance"><div><p class="metric-label">Derived wishlist balance</p><p class="main-number">${fmt(g.total)}</p></div><span class="metric-change">+${g.latest} adds</span></div>${chips(state)}${chart(state,true,false,'balance')}<div class="milestone"><div class="milestone-top"><span>Next milestone</span><strong>${fmt(g.goal)} wishlists</strong></div><div class="progress-track" role="progressbar" aria-label="Wishlist milestone" aria-valuenow="${g.total}" aria-valuemin="0" aria-valuemax="${g.goal}"><div class="progress-fill" style="width:${g.total/g.goal*100}%"></div></div><p>${fmt(g.goal-g.total)} to go · based on the demo balance</p></div>${metrics(state,true)}<button class="outlined-button" data-action="game" data-value="${g.id}">Open activity report</button></div>`;}
function overviewD(state){return `${appbar('Your briefing')}<div class="app-content">${reportDate(state)}<section class="daily-summary"><h3>A good day for your games.</h3><strong>+184</strong><p>new wishlist additions in the latest report.</p><p class="digest-line">159 net additions across ${games.length} games</p></section><div class="section-heading"><h3>Latest update</h3><button class="text-button" data-action="screen" data-value="alerts">Manage alerts</button></div><div class="timeline"><article class="timeline-item"><span class="timeline-icon">${icon('chart')}</span><div class="timeline-content"><strong>Mosslight added 128 wishlists</strong><p>14 removed · 2 purchases · +112 net</p><button class="text-action" data-action="game" data-value="101">View game report ${icon('arrow')}</button><img src="./assets/mosslight.svg" alt="Mosslight forest illustration"></div></article><article class="timeline-item"><span class="timeline-icon">${icon('target')}</span><div class="timeline-content"><strong>12,480 on the way to 15,000</strong><p>Mosslight is 83% of the way to your milestone. Demo derived balance.</p></div></article><article class="timeline-item"><span class="timeline-icon">${icon('games')}</span><div class="timeline-content"><strong>Your other games</strong><p>Orbital Drift +37 · Tiny Harbor +19 additions</p><button class="text-action" data-action="screen" data-value="games">See all games ${icon('arrow')}</button></div></article></div><div class="quiet-banner">${icon('clock')} Report date: Nov 15 · detected on sync</div></div>`;}
function detailScreen(key,state){const g=selectedGame(state);return `${appbar(esc(g.name),true)}<div class="app-content">${reportDate(state)}<p class="metric-label">Derived wishlist balance</p><div class="metric-inline"><p class="main-number">${fmt(g.total)}</p><span class="metric-change">+${g.latest} adds</span></div><p class="metric-sub">Demo baseline + imported daily movements</p>${chips(state)}<label class="form-label" for="${key}-metric">Chart shows</label><select id="${key}-metric" class="form-control" data-field="metric"><option value="adds" ${state.metric==='adds'?'selected':''}>Daily additions</option><option value="net" ${state.metric==='net'?'selected':''}>Daily net change</option><option value="balance" ${state.metric==='balance'?'selected':''}>Derived wishlist balance</option></select>${chart(state,true,key==='B')}${metrics(state,true)}<p class="helper">${fmt(sum(rowsFor(state,true),'purchases'))} purchases · 0 gifts in this interval. All values are synthetic.</p><button class="outlined-button" data-action="screen" data-value="widget">Preview this game’s widget</button><button class="text-button" data-action="screen" data-value="alerts">Customize notifications ${icon('arrow')}</button></div>`;}
const switchControl=(key,field,checked,label)=>`<label class="switch"><input id="${key}-${field}" type="checkbox" data-field="${field}" ${checked?'checked':''} aria-label="${label}"><span></span></label>`;
function alertsScreen(key,state){return `${appbar('Notifications')}<div class="app-content"><h3 class="detail-title screen-heading">Your rules. Your rhythm.</h3><p class="description">Choose what’s worth a notification when a new report is detected.</p><div class="setting-row"><span>Wishlist notifications<small>For monitored games</small></span>${switchControl(key,'notifications',state.notifications,'Wishlist notifications')}</div><div class="settings-group"><label class="form-label" for="${key}-alert-game">Game</label><select id="${key}-alert-game" class="form-control" data-field="gameId">${games.map(g=>`<option value="${g.id}" ${state.gameId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select><label class="form-label" for="${key}-threshold">Notify after new additions</label><select id="${key}-threshold" class="form-control" data-field="threshold" ${state.notifications?'':'disabled'}>${[1,10,25,50,100].map(n=>`<option value="${n}" ${state.threshold===n?'selected':''}>${n} new wishlist${n===1?'':'s'}</option>`).join('')}</select><p class="helper">Counts additions detected since the previous alert.</p></div><div class="settings-group"><div class="setting-row"><span>Daily digest<small>One summary of the latest report</small></span>${switchControl(key,'digest',state.digest,'Daily digest')}</div><div class="setting-row"><span>Quiet hours<small>Hold alerts until quiet hours end</small></span>${switchControl(key,'quiet',state.quiet,'Quiet hours')}</div>${state.quiet?`<div class="form-grid"><label class="form-label">From<input class="form-control" type="time" data-field="quietStart" value="${state.quietStart}"></label><label class="form-label">Until<input class="form-control" type="time" data-field="quietEnd" value="${state.quietEnd}"></label></div>`:''}</div><button class="filled-button" data-action="save-alerts">Apply to ${esc(selectedGame(state).name)}</button><button class="outlined-button" data-action="preview-notification" ${state.notifications?'':'disabled'}>Preview notification</button><p class="helper">Demo preferences stay in this browser session. Notifications are previewed here, not sent to your device.</p>${state.feedback?`<p class="inline-feedback" role="status">${esc(state.feedback)}</p>`:''}</div>`;}
function widgetCard(state){const g=games.find(g=>g.id===state.widgetGame)||games[0];const isBalance=state.widgetMetric==='balance';return `<div class="widget-preview"><div class="widget-preview-header"><span>${esc(g.name)}</span>${icon('chart')}</div><p class="metric-label">${isBalance?'Derived wishlist balance':'Additions · last 7 days'}</p><p class="main-number">${fmt(isBalance?g.total:sum(g.days.slice(-7),'adds'))}</p><div class="widget-bottom"><strong>+${g.latest} latest additions</strong><span>Nov 15 · GMT</span></div></div>`;}
function widgetScreen(key,state){return `${appbar('Home widget')}<div class="app-content"><h3 class="detail-title screen-heading">A little window<br>into your game.</h3><p class="description">Keep the number that matters within reach.</p>${widgetCard(state)}<label class="form-label" for="${key}-widgetGame">Game to show</label><select id="${key}-widgetGame" class="form-control" data-field="widgetGame">${games.map(g=>`<option value="${g.id}" ${state.widgetGame===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select><label class="form-label" for="${key}-widgetMetric">Main number</label><select id="${key}-widgetMetric" class="form-control" data-field="widgetMetric"><option value="balance" ${state.widgetMetric==='balance'?'selected':''}>Derived wishlist balance</option><option value="adds" ${state.widgetMetric==='adds'?'selected':''}>Last 7 days’ additions</option></select><div class="settings-group" style="margin-top:22px"><div class="setting-row"><span>Show reporting date<small>Always visible so older data is clear</small></span>${icon('check')}</div></div><button class="filled-button" data-action="preview-widget">Preview on home screen</button><p class="helper">This browser study previews the widget. Installation on the Android home screen comes with the native app.</p></div>`;}
function settingsScreen(key,state){return `${appbar('Settings')}<div class="app-content"><h3 class="detail-title screen-heading">Just your games.</h3><p class="description">Personal prototype · local reporting</p>${themeSetting(key,state)}<div class="settings-group"><h3>Steamworks connection</h3><label class="form-label" for="${key}-demo-key">Financial API key</label><input id="${key}-demo-key" class="form-control" type="password" value="demonstration-only" readonly aria-describedby="${key}-key-help"><p id="${key}-key-help" class="helper">Demo credential only. Do not enter a real key in this design study.</p><button class="outlined-button" data-action="screen" data-value="add">Add a game by AppID</button></div><div class="settings-group"><h3>Prototype states</h3><div class="setting-row"><span>Offline preview<small>Keep the cached reporting data visible</small></span>${switchControl(key,'offline',state.offline,'Offline preview')}</div><div class="setting-row"><span>Empty portfolio<small>Preview the first-run experience</small></span>${switchControl(key,'empty',state.empty,'Empty portfolio')}</div></div><div class="settings-group"><h3>Reporting</h3><p class="description">Reporting days use GMT. A report date is different from the time your phone last synchronized.</p><button class="outlined-button" data-action="export">Export demo history</button></div><p class="helper">All controls affect the prototype session only. No API calls, credential storage, or Android background jobs run here.</p></div>`;}
function addScreen(state){return `${appbar('Add a game',true)}<div class="app-content"><h3 class="detail-title screen-heading">Start with an AppID.</h3><p class="description">Choose exactly which games you want to monitor.</p><form data-form="add"><label class="form-label" for="demo-appid">Steam AppID</label><input class="form-control" id="demo-appid" name="appid" inputmode="numeric" pattern="[1-9][0-9]{0,9}" maxlength="10" placeholder="For example, 123456" required><p class="helper">Find it in your game’s Steam store URL:<br>store.steampowered.com/app/<strong>123456</strong>/</p><label class="form-label" for="demo-name">Name for this game</label><input class="form-control" id="demo-name" name="gameName" maxlength="60" placeholder="Your game’s name" required><button class="filled-button" type="submit">Preview adding game</button></form><p class="helper">This step simulates setup. It does not validate ownership or request Steam data.</p>${state.feedback?`<div class="inline-feedback" role="status">${esc(state.feedback)}</div>`:''}</div>`;}
function emptyScreen(){return `${appbar('Your games')}<div class="app-content"><div class="empty-state">${icon('games')}<h3>Your next launch starts here.</h3><p>Add your first game to see its wishlist history and set up a home-screen widget.</p><button class="filled-button" data-action="screen" data-value="add">Add your first game</button><button class="outlined-button" data-action="restore">Restore demo portfolio</button></div></div>`;}
function screenContent(key,state){if(state.empty&&['overview','games','detail'].includes(state.screen))return emptyScreen();switch(state.screen){case'detail':return detailScreen(key,state);case'alerts':return alertsScreen(key,state);case'widget':return widgetScreen(key,state);case'settings':return settingsScreen(key,state);case'add':return addScreen(state);case'games':return `${appbar('Your games',true)}<div class="app-content">${reportDate(state)}${gameRows(state)}<button class="filled-button" data-action="screen" data-value="add">Add a game</button></div>`;default:return ({A:overviewA,B:overviewB,C:overviewC,D:overviewD})[key](state);}}
function phone(key,compact=false){const state=states[key];return `<section class="phone ${directions[key].class} ${compact?'compact':''}" data-phone="${key}" ${key==='C'?`data-theme="${resolvedTheme()}"`:""} aria-label="${directions[key].name} interactive phone preview"><div class="statusbar"><span>9:41</span><span class="status-icons">${icon('signal')}${icon('wifi')}${icon('battery')}</span></div><div class="phone-scroll"><div class="screen-enter">${screenContent(key,state)}</div></div><nav class="bottom-nav" aria-label="${directions[key].name} app navigation">${[['overview',key==='D'?'Briefing':key==='B'?'Reports':key==='C'?'Games':'Overview',key==='D'?'home':key==='C'?'games':'chart'],['alerts','Alerts','bell'],['widget','Widget','widget'],['settings','Settings','settings']].map(([screen,label,glyph])=>`<button data-action="screen" data-value="${screen}" ${state.screen===screen||screen==='overview'&&['detail','games','add'].includes(state.screen)?'aria-current="page"':''}><span class="nav-icon">${icon(glyph)}</span>${label}</button>`).join('')}</nav><div class="gesture-bar"></div></section>`;}
function comparison(){return `<section class="studio-intro"><div><h1>One app. Four points of view.</h1><p>Same games, same data. Four ways to keep a finger on your wishlist growth.<br>Explore a direction to try the flow, filters, alerts, and home widget.</p></div><p class="intro-side">Designed for Android.<br>Choose the experience first;<br>we’ll build the native app next.</p></section><div class="compare-grid">${Object.entries(directions).map(([key,d])=>`<article><div class="direction-heading"><h2><span class="direction-key">${key}</span>${d.name}</h2><a href="?variant=${key}" aria-label="Explore ${d.name}">${icon('up')}</a></div>${phone(key,true)}<p class="direction-summary">${d.summary}</p><a class="explore-button" href="?variant=${key}">Explore ${d.name}${icon('arrow')}</a></article>`).join('')}</div>`;}
function detail(key){const d=directions[key],state=states[key];return `<div class="detail-layout"><section class="direction-info"><a class="back-link" href="?view=compare">${icon('back')} All four directions</a><span class="direction-key">Direction ${key}</span><h1>${d.name}</h1><p class="info-subtitle">${d.subtitle}</p>${appearanceControls(key)}<p>${d.purpose}</p><ul class="info-list">${d.features.map(f=>`<li>${icon('check')}<span>${f}</span></li>`).join('')}</ul><div class="palette" aria-label="Direction palette">${paletteFor(key).map(c=>`<span style="background:${c}"></span>`).join('')}</div>${key==='C'?`<div class="confirmed-direction">${icon('check')} Selected for Android</div>`:`<button class="select-direction" data-choose="${key}">${state.selected?'Direction selected':'Choose this direction'}${icon(state.selected?'check':'arrow')}</button>`}${key!=='C'&&state.selected?`<div class="selection-result" role="status">Selected: ${key} · ${d.name}. Share this choice in the conversation to guide the Android implementation.</div>`:''}<p class="prototype-note">Design study only · no connection to Steam</p></section>${phone(key)}<aside class="side-notes"><div><h2>Take it for a spin</h2><p>The phone is interactive. Start here, or use its navigation.</p><ul class="interaction-list">${[['overview','Explore the main screen'],['detail','Open a game report'],['alerts','Tune your notifications'],['widget','Configure the home widget'],['add','Try adding an AppID']].map(([screen,label])=>`<li><button data-jump="${screen}" data-key="${key}">${label}${icon('arrow')}</button></li>`).join('')}</ul></div><div><h2>The same direction, at home</h2><p>A small companion for the number you check most.</p><div class="widget-shell phone ${d.class}" ${key==='C'?`data-theme="${resolvedTheme()}"`:""}>${widgetCard(state)}</div><div class="note-block"><h3>The tradeoff</h3><p>${d.risk}</p></div><div class="note-block"><h3>What makes it different</h3><p>${d.signature}</p></div></div><div class="state-readout">Preview state · ${key} / ${esc(state.screen)} / ${state.range==='custom'?`${state.customStart} → ${state.customEnd}`:`${state.range} days`} / ${esc(selectedGame(state).name)}<br>${state.offline?'Offline cache':'Demo data'} · ${state.notifications?'Alerts on':'Alerts off'} · ${state.empty?'Empty portfolio':'3 games'} · changes are memory-only</div></aside></div>`;}
function render(){document.getElementById('studio').innerHTML=compare?comparison():detail(activeKey);document.getElementById('variant-tabs').innerHTML=Object.entries(directions).map(([key,d])=>`<a href="?variant=${key}" ${!compare&&activeKey===key?'aria-current="page"':''} aria-label="Direction ${key}: ${d.name}"><span>${key}</span><span class="tab-name">${d.name}</span></a>`).join('');document.getElementById('previous').innerHTML=icon('back');document.getElementById('next').innerHTML=icon('arrow');}
function navigate(key,toCompare=false){activeKey=key;compare=toCompare;const url=new URL(location.href);url.search='';if(toCompare)url.searchParams.set('view','compare');else url.searchParams.set('variant',key);url.searchParams.set('theme',states.C.theme);history.pushState({},'',url);render();window.scrollTo({top:0,behavior:'instant'});}
function refreshPhone(key,{preserveScroll=false}={}){const old=document.querySelector(`[data-phone="${key}"]`);const scroll=old?.querySelector('.phone-scroll').scrollTop||0;if(old){old.outerHTML=phone(key,compare);if(preserveScroll)document.querySelector(`[data-phone="${key}"] .phone-scroll`).scrollTop=scroll;}if(!compare){const current=document.querySelector('.state-readout');if(current)current.innerHTML=`Preview state · ${key} / ${states[key].screen} / ${states[key].range} days / ${esc(selectedGame(states[key]).name)}<br>${states[key].offline?'Offline cache':'Demo data'} · ${states[key].notifications?'Alerts on':'Alerts off'} · ${states[key].empty?'Empty portfolio':'3 games'} · changes are memory-only`;const shell=document.querySelector('.widget-shell');if(shell){shell.innerHTML=widgetCard(states[key]);if(key==='C')shell.dataset.theme=resolvedTheme();}}}
function snackbar(key,message){const target=document.querySelector(`[data-phone="${key}"]`);target?.querySelector('.snackbar')?.remove();const el=document.createElement('div');el.className='snackbar';el.setAttribute('role','status');el.textContent=message;target?.append(el);setTimeout(()=>el.remove(),5000);}
function changeScreen(key,screen){states[key].feedback='';states[key].screen=screen;if(screen==='widget')states[key].widgetGame=states[key].gameId;refreshPhone(key);}
function exportDemo(key){const state=states[key],rows=rowsFor(state,state.screen==='detail');const csv=['date_gmt,additions,removals,purchases,gifts,net_change,derived_balance',...rows.map(r=>[r.date,r.adds,r.deletes,r.purchases,r.gifts,r.net,r.balance].join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='wishlist-demo-report.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);snackbar(key,'Synthetic report exported as CSV.');}
document.addEventListener('click',event=>{
 const appearance=event.target.closest('[data-appearance]');if(appearance){setTheme(appearance.dataset.appearance);return;}
 const anchor=event.target.closest('a[href]');if(anchor&&anchor.origin===location.origin&&anchor.pathname===location.pathname){const url=new URL(anchor.href);event.preventDefault();navigate(url.searchParams.get('variant')||activeKey,url.searchParams.get('view')==='compare');return;}
 const choice=event.target.closest('[data-choose]');if(choice){const key=choice.dataset.choose;Object.values(states).forEach(s=>s.selected=false);states[key].selected=true;render();return;}
 const jump=event.target.closest('[data-jump]');if(jump){changeScreen(jump.dataset.key,jump.dataset.jump);return;}
 const button=event.target.closest('[data-action]');if(!button)return;const key=button.closest('[data-phone]')?.dataset.phone;if(!key)return;const state=states[key];switch(button.dataset.action){
 case'screen':changeScreen(key,button.dataset.value);break;
 case'back':changeScreen(key,'overview');break;
 case'game':state.gameId=Number(button.dataset.value);state.widgetGame=state.gameId;state.metric='adds';changeScreen(key,'detail');break;
 case'select-game':state.gameId=Number(button.dataset.value);refreshPhone(key);break;
 case'range':state.range=button.dataset.value;refreshPhone(key,{preserveScroll:true});break;
 case'sync':snackbar(key,state.offline?'Offline preview: showing cached Nov 15 report.':'Demo sync complete. No Steam request was made.');break;
 case'save-alerts':state.feedback=`Demo rules applied to ${selectedGame(state).name}: ${state.notifications?`alert after ${state.threshold} new additions`:'notifications off'}. ${state.quiet?`Quiet hours ${state.quietStart}–${state.quietEnd}.`:''}`;refreshPhone(key,{preserveScroll:true});break;
 case'preview-notification':snackbar(key,`${selectedGame(state).name} · +${selectedGame(state).latest} new wishlist additions. Nov 15 report. Demo notification.`);break;
 case'preview-widget':state.feedback='';changeScreen(key,'widget-home');break;
 case'export':exportDemo(key);break;
 case'restore':state.empty=false;changeScreen(key,'overview');break;
 }
});
document.addEventListener('change',event=>{const input=event.target.closest('[data-field]');if(!input)return;const key=input.closest('[data-phone]').dataset.phone;const state=states[key];if(input.dataset.field==='theme'){setTheme(input.value);return;}let value=input.type==='checkbox'?input.checked:input.value;if(['gameId','widgetGame','threshold'].includes(input.dataset.field))value=Number(value);state[input.dataset.field]=value;state.feedback='';refreshPhone(key,{preserveScroll:true});});
document.addEventListener('submit',event=>{if(event.target.dataset.form!=='add')return;event.preventDefault();const key=event.target.closest('[data-phone]').dataset.phone;const form=new FormData(event.target);states[key].feedback=`${String(form.get('gameName')).trim()} (AppID ${form.get('appid')}) would be added to your monitored games. This is a setup preview; no data was fetched.`;refreshPhone(key);});
function cycle(offset){const keys=Object.keys(directions);navigate(keys[(keys.indexOf(activeKey)+offset+keys.length)%keys.length]);}
document.getElementById('previous').addEventListener('click',()=>cycle(-1));document.getElementById('next').addEventListener('click',()=>cycle(1));
document.addEventListener('keydown',event=>{if(event.target.closest('input,textarea,select,button,[contenteditable="true"]'))return;if(event.key==='ArrowLeft'){event.preventDefault();cycle(-1);}if(event.key==='ArrowRight'){event.preventDefault();cycle(1);}});
window.addEventListener('popstate',()=>{const p=new URL(location.href).searchParams;activeKey=directions[p.get('variant')]?p.get('variant'):'C';compare=p.get('view')==='compare';states.C.theme=themeModes.includes(p.get('theme'))?p.get('theme'):'system';render();});
// The home-screen view is a simulation, not an Android widget installation.
const originalScreenContent=screenContent;
screenContent=function(key,state){if(state.screen==='widget-home')return `${appbar('Home preview',true)}<div class="app-content"><p class="description screen-heading">Your widget on a quiet home screen.</p><div class="demo-home"><p class="home-time">09:41</p><p class="home-date">Monday, November 16</p><button class="widget-open" data-action="game" data-value="${state.widgetGame}" aria-label="Open widget’s game report">${widgetCard(state)}</button><p class="helper">Tap the widget to open its game report.</p></div><button class="outlined-button" data-action="screen" data-value="widget">Back to widget settings</button><p class="helper">Home-screen simulation · synthetic data</p></div>`;return originalScreenContent(key,state);};
systemTheme.addEventListener('change',()=>{if(states.C.theme==='system'){refreshPhone('C',{preserveScroll:true});const panel=document.querySelector('.appearance-panel');if(panel)panel.outerHTML=appearanceControls('C');const palette=panel?.closest('.direction-info')?.querySelector('.palette');if(palette)palette.innerHTML=paletteFor('C').map(color=>`<span style="background:${color}"></span>`).join('');}});
render();
